const item = $input.first();
const emailMeta = $('Code — Filtrar PDFs').item.json;
const pdfBinary = $('Code — Filtrar PDFs').item.binary || {};

let d;
try {
  const raw = item.json?.text || item.json?.output || item.json?.response || '';
  if (!raw) throw new Error('LLM sem conteúdo');
  const clean = raw.replace(/```json\s*/gi,'').replace(/```\s*/g,'').trim();
  d = JSON.parse(clean);
} catch(e) {
  return [{ json: { _erro: true, _pular: true,
    email_messageId: emailMeta.messageId,
    email_fileName: emailMeta.fileName
  }}];
}

const numFields = ['aluguel_bruto','energia','iptu_valor','taxa_administracao',
  'total_credito','total_debito','valor_liquido','multa_atraso','reparos_debito'];
for (const f of numFields) {
  if (typeof d[f] === 'string') d[f] = parseFloat(d[f].replace(/\./g,'').replace(',','.')) || 0;
  if (d[f] == null) d[f] = 0;
}

const dateFields = ['vencimento_aluguel','data_pagamento','termino_contrato','periodo_inicio','periodo_fim'];
for (const f of dateFields) {
  if (d[f] && d[f] !== 'null') {
    const p = d[f].split('/');
    if (p.length === 3) d[f] = `${p[2]}-${p[1]}-${p[0]}`;
  } else { d[f] = null; }
}

// mes_ref = data do vencimento em DD/MM/AAAA
const ref = d.vencimento_aluguel || d.periodo_inicio || '';
const rp = ref.split('-');
if (rp.length === 3) {
  d.mes_ref = `${rp[2]}/${rp[1]}/${rp[0]}`;
} else {
  d.mes_ref = '';
}

// competencia = MM/AAAA (como era antes)
d.competencia = rp.length >= 2 ? `${rp[1]}/${rp[0]}` : '';

// ====== CORRECAO: cálculo determinístico de atraso ======
// Ignora flag do LLM para evitar falsos positivos (IRRF, Tx Admin, IPTU).
// Só é atraso se: data_pagamento > vencimento_aluguel E multa_atraso > 0.
// Pago na data ou antes => NUNCA atraso.
let atraso = false;
if (d.data_pagamento && d.vencimento_aluguel) {
  const pago = new Date(d.data_pagamento + 'T00:00:00');
  const venc = new Date(d.vencimento_aluguel + 'T00:00:00');
  const diasAtraso = Math.round((pago - venc) / 86400000);
  if (diasAtraso > 0 && d.multa_atraso > 0) {
    atraso = true;
  }
  d.dias_atraso = diasAtraso > 0 ? diasAtraso : 0;
} else {
  d.dias_atraso = 0;
}
d.pagamento_com_atraso = atraso;
// ========================================================

if (!d.data_pagamento) d.status_pagamento = 'Em aberto';
else if (d.pagamento_com_atraso) d.status_pagamento = 'Pago com atraso';
else d.status_pagamento = 'Pago';

d._erro = false;
d.email_messageId = emailMeta.messageId || '';
d.email_fileName  = emailMeta.fileName  || '';
const fromRaw = emailMeta.emailFrom;
d.email_from = typeof fromRaw === 'string' ? fromRaw : (fromRaw?.value?.[0]?.address || fromRaw?.text || '');
d.processado_em = new Date().toISOString();

return [{ json: d, binary: pdfBinary }];

// Busca o mapa de colunas do Coda (nome -> id)
const codaCols = $('HTTP — GET Colunas Coda').first().json;
const colItems = codaCols.items || codaCols || [];
const colMap = {};
for (const col of colItems) {
  colMap[col.name.trim().toLowerCase()] = col.id;
}

// Dados extraídos do extrato
const d         = $('Code — Sanitizar JSON1').item.json;
const driveFile = $('Google Drive — Upload PDF1').item.json;
const fileId    = driveFile.id || driveFile.fileId;
const driveUrl  = `https://drive.google.com/uc?export=download&id=${fileId}`;

const str  = v => (v == null || v === 'null' || v === 'undefined' ? '' : String(v).trim());
const num  = v => { const n = Number(v); return (isNaN(n) || !isFinite(n)) ? 0 : n; };
const bool = v => (v === true || v === 'true');
const isoDate = v => {
  if (!v || v === 'null' || v === '') return null;
  const dt = new Date(v);
  return isNaN(dt.getTime()) ? null : dt.toISOString();
};

// Mapeamento: chave = nome EXATO da coluna Coda (lowercase)
// Colunas calculadas (Imóveis, Endereço, Locatário, Data Referência, Proprietário) NÃO incluídas
const mapping = {
  'cód wpa':                     num(d.codigo_wpa),
  'parcela':                     num(d.parcela),
  'vencimento aluguel':          isoDate(d.vencimento_aluguel),
  'data pagamento':              isoDate(d.data_pagamento),
  'nome locatario':              str(d.locatario_nome),
  'locatario cnpj':              num(d.locatario_cnpj),
  'periodo inicio':              str(d.periodo_inicio),
  'periodo fim':                 str(d.periodo_fim),
  'aluguel bruto':               num(d.aluguel_bruto),
  'valor energia':               num(d.energia),
  'valor iptu':                  num(d.iptu_valor),
  'iptu parcela atual':          num(d.iptu_parcela_atual),
  'iptu total de parcelas':      num(d.iptu_total_parcelas),
  'taxa administração':          num(d.taxa_administracao),
  'reparos debito':              num(d.reparos_debito),
  'multa atraso':                num(d.multa_atraso),
  'total crédito':               num(d.total_credito),
  'total débito':                num(d.total_debito),
  'valor líquido':               num(d.valor_liquido),
  'cnpj locador':                str(d.locador_cnpj),
  'banco':                       str(d.banco),
  'agencia':                     str(d.agencia),
  'conta':                       str(d.conta),
  'tipo de conta':               str(d.tipo_conta || 'Corrente'),
  'rateio percentual':           num(d.rateio_percentual || 100),
  'pagamento com atraso':        bool(d.pagamento_com_atraso),
  'parcelas atrasadas quitadas': num(d.parcelas_atrasadas_quitadas),
  'observacoes':                 str(d.observacoes),
  'competencia':                 str(d.competencia),
  'status pagamento':            str(d.status_pagamento || 'Em aberto'),
  'nome  do arquivo email':      str(d.email_fileName),
  'email enviado para':          str(typeof d.email_from === 'string' ? d.email_from : (d.email_from?.value?.[0]?.address || d.email_from?.text || '')),
  'processado pela altomaçao':   isoDate(d.processado_em) || new Date().toISOString(),
};

// Monta cells apenas para colunas que existem no Coda
const cells = [];
const missing = [];
for (const [name, value] of Object.entries(mapping)) {
  if (value === null || value === undefined) continue;
  const id = colMap[name];
  if (id) {
    cells.push({ column: id, value });
  } else {
    missing.push(name);
  }
}

// keyColumns: mesmo contrato + mesma competência = atualiza; mês diferente = nova row
const keyColNames = ['cód wpa', 'competencia'];
const keyColumns = keyColNames
  .map(n => colMap[n])
  .filter(Boolean);

const payload = JSON.stringify({
  rows: [{ cells }],
  keyColumns
});

return [{ json: {
  _upsertPayload: payload,
  _fileId: fileId,
  _missingColumns: missing,
  _colunasEncontradas: cells.length,
  _colunasDisponiveis: Object.keys(colMap)
}}];

const items = [];
const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
for (const key of binaryKeys) {
  const bin = item.binary[key];
  const isPdf = bin.mimeType === 'application/pdf' ||
    bin.fileName?.toLowerCase().endsWith('.pdf') ||
    key.toLowerCase().includes('pdf');
  if (isPdf) {
    items.push({
      json: {
        messageId: item.json.id,
        emailSubject: item.json.subject || '',
        emailDate: item.json.date || new Date().toISOString(),
        emailFrom: item.json.from,
        fileName: bin.fileName || `extrato_${Date.now()}.pdf`,
        binaryKey: key
      },
      binary: { data: bin }
    });
  }
}
if (items.length === 0) return [{ json: { skip: true, messageId: item.json.id } }];
return items;
